@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @FilteredTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @TodoTasks.Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @InProgressTasks.Count</span>
        <span class="stat-item"><strong>Done:</strong> @DoneTasks.Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @OverdueTasks.Count</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" placeholder="Search tasks by title..." @bind="_searchQuery" @bind:event="oninput" class="form-control" />
    </div>

    <!-- Kanban Columns -->
    <div class="kanban-board">
        <div class="kanban-column">
            <div class="column-header">
                <h3>To Do <span class="badge">@TodoTasks.Count</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in TodoTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-secondary" @onclick="() => MoveRight(task)">Move Right &raquo;</button>
                        </div>
                    </div>
                }
            </div>
            @if (_showFormForColumn == "To Do")
            {
                <div class="add-task-form">
                    <input type="text" placeholder="Title" @bind="_newTitle" class="form-control" />
                    <input type="text" placeholder="Assignee" @bind="_newAssignee" class="form-control" />
                    <select @bind="_newPriority" class="form-control">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" @bind="_newDueDate" class="form-control" />
                    <div class="form-buttons">
                        <button class="btn btn-primary btn-sm" @onclick="SaveTask">Save</button>
                        <button class="btn btn-secondary btn-sm" @onclick="CancelForm">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm add-task-btn" @onclick='() => ShowForm("To Do")'>+ Add Task</button>
            }
        </div>

        <div class="kanban-column">
            <div class="column-header">
                <h3>In Progress <span class="badge">@InProgressTasks.Count</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in InProgressTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-secondary" @onclick="() => MoveLeft(task)">&laquo; Move Left</button>
                            <button class="btn btn-sm btn-secondary" @onclick="() => MoveRight(task)">Move Right &raquo;</button>
                        </div>
                    </div>
                }
            </div>
            @if (_showFormForColumn == "In Progress")
            {
                <div class="add-task-form">
                    <input type="text" placeholder="Title" @bind="_newTitle" class="form-control" />
                    <input type="text" placeholder="Assignee" @bind="_newAssignee" class="form-control" />
                    <select @bind="_newPriority" class="form-control">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" @bind="_newDueDate" class="form-control" />
                    <div class="form-buttons">
                        <button class="btn btn-primary btn-sm" @onclick="SaveTask">Save</button>
                        <button class="btn btn-secondary btn-sm" @onclick="CancelForm">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm add-task-btn" @onclick='() => ShowForm("In Progress")'>+ Add Task</button>
            }
        </div>

        <div class="kanban-column">
            <div class="column-header">
                <h3>Done <span class="badge">@DoneTasks.Count</span></h3>
            </div>
            <div class="column-body">
                @foreach (var task in DoneTasks)
                {
                    <div class="task-card">
                        <div class="task-title">@task.Title</div>
                        <div class="task-assignee">@task.Assignee</div>
                        <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                        <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                        <div class="task-actions">
                            <button class="btn btn-sm btn-secondary" @onclick="() => MoveLeft(task)">&laquo; Move Left</button>
                        </div>
                    </div>
                }
            </div>
            @if (_showFormForColumn == "Done")
            {
                <div class="add-task-form">
                    <input type="text" placeholder="Title" @bind="_newTitle" class="form-control" />
                    <input type="text" placeholder="Assignee" @bind="_newAssignee" class="form-control" />
                    <select @bind="_newPriority" class="form-control">
                        <option value="High">High</option>
                        <option value="Medium">Medium</option>
                        <option value="Low">Low</option>
                    </select>
                    <input type="date" @bind="_newDueDate" class="form-control" />
                    <div class="form-buttons">
                        <button class="btn btn-primary btn-sm" @onclick="SaveTask">Save</button>
                        <button class="btn btn-secondary btn-sm" @onclick="CancelForm">Cancel</button>
                    </div>
                </div>
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm add-task-btn" @onclick='() => ShowForm("Done")'>+ Add Task</button>
            }
        </div>
    </div>
}

@code {
    private List<TaskItem> _tasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;

    private string? _showFormForColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    private static readonly string[] ColumnOrder = ["To Do", "In Progress", "Done"];

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(_searchQuery)
        ? _tasks
        : _tasks.Where(t => t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> OverdueTasks => FilteredTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = ColumnOrder[currentIndex - 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                _tasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, task.Status);
        if (currentIndex >= ColumnOrder.Length - 1) return;

        var newStatus = ColumnOrder[currentIndex + 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                _tasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowForm(string column)
    {
        _showFormForColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelForm()
    {
        _showFormForColumn = null;
    }

    private async Task SaveTask()
    {
        if (string.IsNullOrWhiteSpace(_newTitle)) return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // If the task was created in a column other than "To Do", update its status
            if (_showFormForColumn != "To Do" && _showFormForColumn is not null)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _showFormForColumn);
                created = created with { Status = _showFormForColumn };
            }
            _tasks.Add(created);
            _showFormForColumn = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }
}

